class Solution {
    struct TrieNode {
        TrieNode* children[26];
        bool isEnd;
        TrieNode() {
            for (int i = 0; i < 26; i++) children[i] = nullptr;
            isEnd = false;
        }
    };
public:
    string replaceWords(vector<string>& dictionary, string sentence) {
        TrieNode* root = new TrieNode();
        for (const string& word : dictionary) {
            TrieNode* node = root;
            for (char c : word) {
                int idx = c - 'a';
                if (!node->children[idx]) {
                    node->children[idx] = new TrieNode();
                }
                node = node->children[idx];
            }
            node->isEnd = true;
        }

        string result;
        result.reserve(sentence.size());
        int n = sentence.size();
        int i = 0;
        while (i < n) {
            int wordStart = i;
            TrieNode* node = root;
            int matchEnd = -1;
            while (i < n && sentence[i] != ' ') {
                int idx = sentence[i] - 'a';
                if (node->children[idx]) {
                    node = node->children[idx];
                    i++;
                    if (node->isEnd) {
                        matchEnd = i - 1;
                        break;
                    }
                } else {
                    break;
                }
            }
            while (i < n && sentence[i] != ' ') i++;

            if (matchEnd != -1) {
                result.append(sentence, wordStart, matchEnd - wordStart + 1);
            } else {
                result.append(sentence, wordStart, i - wordStart);
            }

            if (i < n && sentence[i] == ' ') {
                result.push_back(' ');
                i++;
            }
        }
        return result;
    }
};
